/**
 * Launcher generation and Web UI helpers for dsh-web-launcher.
 * @module dsh-web-launcher/launcher
 */

import { spawn, spawnSync } from 'node:child_process'
import { existsSync, mkdirSync, readFileSync, writeFileSync } from 'node:fs'
import { fileURLToPath } from 'node:url'
import { join } from 'node:path'

/** ASCII-only .cmd template with __PORT__ / __URL__ placeholders. */
const TEMPLATE_PATH = fileURLToPath(new URL('./template.cmd.txt', import.meta.url))

/**
 * Resolve the Windows desktop directory, trying common locations.
 * @returns the desktop directory, or null on non-Windows hosts.
 */
export function resolveDesktopDir() {
  if (process.platform !== 'win32') return null
  const candidates = [
    process.env.USERPROFILE && join(process.env.USERPROFILE, 'Desktop'),
    process.env.ONE_DRIVE && join(process.env.ONE_DRIVE, 'Desktop'),
    process.env.USERPROFILE && join(process.env.USERPROFILE, 'OneDrive', 'Desktop'),
  ]
  for (const dir of candidates) {
    if (dir && existsSync(dir)) return dir
  }
  const fallback = process.env.USERPROFILE && join(process.env.USERPROFILE, 'Desktop')
  if (fallback) mkdirSync(fallback, { recursive: true })
  return fallback
}

/**
 * Resolve the private directory that hosts the .cmd launcher (kept off the
 * desktop so only the app shortcut is visible there).
 * @returns the launcher directory, or null on non-Windows hosts.
 */
export function resolveLauncherDir() {
  if (process.platform !== 'win32') return null
  const base = process.env.LOCALAPPDATA ?? ''
  if (base === '') return null
  return join(base, 'dsh-web-launcher')
}

/**
 * Render the launcher template with concrete port and URL values.
 * @param options - port and url.
 * @returns the full .cmd file content.
 */
export function renderTemplate({ port, url }) {
  const raw = readFileSync(TEMPLATE_PATH, 'utf8')
  return raw.replaceAll('__PORT__', String(port)).replaceAll('__URL__', url)
}

/**
 * Write (or refresh) the launcher .cmd. It lives in the private launcher
 * directory (off the desktop) so the desktop only shows the app shortcut.
 * @param options - port, shortcutName and launcherDir (resolved by the caller).
 * @returns whether the file was newly created and its path.
 */
export function ensureLauncher({ port, shortcutName, launcherDir }) {
  const dir = launcherDir ?? resolveLauncherDir()
  if (!dir) return { created: false, path: null, reason: 'no-launcher-dir' }
  mkdirSync(dir, { recursive: true })
  const target = join(dir, shortcutName)
  const created = !existsSync(target)
  writeFileSync(target, renderTemplate({ port, url: `http://127.0.0.1:${port}` }), 'utf8')
  return { created, path: target }
}

/**
 * Create (or refresh) an app-style desktop shortcut (.lnk) that points at the
 * launcher .cmd with the whale icon, so the entry looks like a real app.
 * @param options - shortcutName, launcherDir, linkName, desktopDir, iconPath.
 * @returns whether the shortcut was newly created and its path.
 */
export function ensureShortcut({ shortcutName, launcherDir, linkName, desktopDir, iconPath }) {
  const dir = desktopDir ?? resolveDesktopDir()
  if (!dir) return { created: false, path: null, reason: 'no-desktop' }
  const cmdPath = join(launcherDir ?? resolveLauncherDir(), shortcutName)
  const target = join(dir, linkName)
  const created = !existsSync(target)
  const comspec = process.env.ComSpec || 'C:\\Windows\\System32\\cmd.exe'
  const q = (s) => `'${String(s).replace(/'/g, "''")}'`
  const ps = [
    '$w=New-Object -ComObject WScript.Shell',
    `$s=$w.CreateShortcut(${q(target)})`,
    `$s.TargetPath=${q(comspec)}`,
    `$s.Arguments=${q(`/c ""${cmdPath}""`)}`,
    `$s.IconLocation=${q(`${iconPath},0`)}`,
    `$s.WorkingDirectory=${q(dir)}`,
    "$s.Description='Start DeepSeek Harness Web'",
    '$s.Save()',
  ].join('; ')
  const result = spawnSync('powershell.exe', ['-NoProfile', '-NonInteractive', '-Command', ps], { stdio: 'ignore' })
  if (result.error || result.status !== 0) {
    throw new Error(`shortcut creation failed (${result.error?.message ?? `powershell exit ${result.status}`})`)
  }
  return { created, path: target }
}

/**
 * Probe whether a DSH Web server responds on the given port.
 * @param port - local port to probe.
 * @param timeoutMs - probe timeout in milliseconds.
 */
export async function serverStatus(port, timeoutMs = 1500) {
  try {
    const res = await fetch(`http://127.0.0.1:${port}`, { signal: AbortSignal.timeout(timeoutMs) })
    return { running: true, httpStatus: res.status }
  } catch {
    return { running: false, httpStatus: null }
  }
}

/**
 * Open a URL in the default browser, detached from this process.
 * @param url - the URL to open.
 */
export function openBrowser(url) {
  const platform = process.platform
  if (platform === 'win32') {
    spawn('cmd', ['/c', 'start', '', url], { detached: true, stdio: 'ignore' }).unref()
  } else if (platform === 'darwin') {
    spawn('open', [url], { detached: true, stdio: 'ignore' }).unref()
  } else {
    spawn('xdg-open', [url], { detached: true, stdio: 'ignore' }).unref()
  }
}
